import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function intOf(v: unknown, label: string): number | null {
  if (v === undefined || v === null || v === '') {
    return null;
  }
  if (typeof v !== 'string' || !/^\d+$/.test(v)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값이 올바르지 않습니다.');
  }
  return Number(v);
}

@Controller('api/v1')
export class FnSir00301Controller {
  @Get('/help-contents')
  async listHelpContents(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const q = checks.queryOf(req.query);
    const menuId = intOf(q['menuId'], '대상 메뉴');
    const page = intOf(q['page'], '페이지') ?? 0;
    let size = intOf(q['size'], '크기') ?? DEFAULT_SIZE;
    if (size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '크기 값이 올바르지 않습니다.');
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }
    const rawKeyword = q['keyword'];
    if (rawKeyword !== undefined && rawKeyword !== null && typeof rawKeyword !== 'string') {
      throw new ApiError(400, 'VALIDATION_FAILED', '검색어 값이 올바르지 않습니다.');
    }
    const keyword = typeof rawKeyword === 'string' ? rawKeyword.trim() : '';
    return transaction(async (db) => {
      let where = " WHERE use_yn = '사용'";
      const params: Record<string, unknown> = {};
      if (menuId !== null) {
        where += ' AND menu_id = CAST(:menuId AS bigint)';
        params.menuId = menuId;
      }
      if (keyword !== '') {
        where += " AND (title ILIKE '%' || :keyword || '%' OR content ILIKE '%' || :keyword || '%')";
        params.keyword = keyword;
      }
      const totalRows = await db.query('SELECT COUNT(*) AS "total" FROM help_content' + where, params);
      const total = Number(totalRows[0].total);
      // 해당 기능(메뉴)에 등록된 도움말이 없으면 도움말 미제공 안내
      if (total === 0 && menuId !== null && keyword === '') {
        throw new ApiError(404, 'HELP_CONTENT_NOT_FOUND', '해당 기능에 등록된 도움말이 없습니다.');
      }
      const listParams = { ...params, size, offset: page * size };
      const items = await db.query(
        'SELECT help_content_id AS "helpContentId", menu_id AS "menuId", title AS "title", content AS "content", manual_version AS "manualVersion"' +
          ' FROM help_content' +
          where +
          ' ORDER BY help_content_id LIMIT :size OFFSET :offset',
        listParams,
      );
      return { items, page, size, total };
    });
  }

  @Get('/help-contents/:helpContentId')
  async getHelpContent(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const helpContentId = intOf(req.params['helpContentId'], '도움말 ID');
    if (helpContentId === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '도움말 ID 값이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT help_content_id AS "helpContentId", menu_id AS "menuId", title AS "title", content AS "content", manual_version AS "manualVersion"' +
          ' FROM help_content' +
          " WHERE help_content_id = CAST(:helpContentId AS bigint) AND use_yn = '사용'",
        { helpContentId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'HELP_CONTENT_NOT_FOUND', '요청한 도움말이 없거나 사용하지 않는 도움말입니다.');
      }
      return rows[0];
    });
  }
}

