import { useState } from 'react';
import {
  call,
  useData,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Field,
  TextInput,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const SIZE = 20;

export default function FnSir00301Page({ role, notify }: PageProps) {
  const [menuId, setMenuId] = useState<number | string>('');
  const [keyword, setKeyword] = useState('');
  const [applied, setApplied] = useState<{ menuId: number | string; keyword: string }>({ menuId: '', keyword: '' });
  const [page, setPage] = useState(0);
  const [selectedId, setSelectedId] = useState<unknown>(undefined);

  const list = useData<Page>(
    () => call<Page>('GET', '/help-contents', role, undefined, { menuId: applied.menuId, keyword: applied.keyword, page, size: SIZE }),
    [role, applied, page],
  );

  const detail = useData<Row | undefined>(
    () => (selectedId === undefined ? Promise.resolve(undefined) : call('GET', '/help-contents/' + String(selectedId), role)),
    [role, selectedId],
  );

  const search = () => {
    setPage(0);
    setApplied({ menuId, keyword });
  };

  const reset = () => {
    setMenuId('');
    setKeyword('');
    setPage(0);
    setApplied({ menuId: '', keyword: '' });
  };

  const rows = list.data ? list.data.items : [];
  const total = list.data ? list.data.total : 0;

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>검색 결과</h2>
        <Tiles items={[['도움말 건수', total]]} />
      </section>
      <section className="box span-8">
        <h2>도움말 검색</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="대상 메뉴">
            <LookupSelect table="menu" role={role} value={menuId} onChange={setMenuId} placeholder="전체" />
          </Field>
          <Field label="도움말 검색어">
            <TextInput value={keyword} onChange={setKeyword} placeholder="제목 또는 내용" />
          </Field>
        </Filters>
      </section>
      <section className="box span-12">
        <h2>도움말 목록</h2>
        <Band total={total} />
        {list.error ? <ErrorText text={list.error} /> : null}
        <DataTable
          columns={[
            { key: 'helpContentId', label: '도움말 ID' },
            { key: 'menuId', label: '대상 메뉴', render: (r) => <RefName table="menu" role={role} value={r.menuId} /> },
            { key: 'title', label: '도움말 제목' },
            { key: 'manualVersion', label: '매뉴얼 버전' },
          ]}
          rows={rows}
          onRowClick={(r) => setSelectedId(r.helpContentId)}
          empty="도움말이 없습니다. 도움말 미제공 기능입니다."
        />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>
      {selectedId !== undefined ? (
        <Drawer title="도움말" onClose={() => setSelectedId(undefined)}>
          {detail.error ? <ErrorText text={detail.error} /> : null}
          {detail.data ? (
            <Pairs
              items={[
                ['도움말 ID', String(detail.data.helpContentId)],
                ['대상 메뉴', <RefName table="menu" role={role} value={detail.data.menuId} />],
                ['도움말 제목', String(detail.data.title ?? '')],
                ['매뉴얼 버전', String(detail.data.manualVersion ?? '')],
                ['도움말 내용', <div>{String(detail.data.content ?? '')}</div>],
              ]}
            />
          ) : null}
        </Drawer>
      ) : null}
    </div>
  );
}
